window.AUTH=window.AUTH||{};window.AUTH["21-1270"]={"d":"21-1270","id":"2022/21-1270","n":"MOAC Mall Holdings LLC v. Transform Holdco LLC","briefs":[{"k":"petitioner","label":"Brief of petitioner MOAC Mall Holdings LLC","date":"2022-08-29","url":"https://www.supremecourt.gov/DocketPDF/21/21-1270/236576/20220829135539782_21-1270%20Brief%20for%20the%20Petitioner.pdf","side":"pet","n":64},{"k":"united-states","label":"Brief amicus curiae of United States","date":"2022-09-06","url":"https://www.supremecourt.gov/DocketPDF/21/21-1270/237191/20220906193209159_21-1270tsacUnitedStates.pdf","side":"us","n":72},{"k":"respondent","label":"Brief of respondent Transform Holdco LLC","date":"2022-10-19","url":"https://www.supremecourt.gov/DocketPDF/21/21-1270/243486/20221019170309522_No.%2021-1270_Brief%20for%20Respondent.pdf","side":"res","n":98},{"k":"reply","label":"Reply of petitioner MOAC Mall Holdings LLC","date":"2022-11-18","url":"https://www.supremecourt.gov/DocketPDF/21/21-1270/246957/20221118130045637_21-1270%20Reply%20Brief%20of%20Petitioner.pdf","side":"pet","n":52}],"opinion":"https://www.supremecourt.gov/opinions/22pdf/598us1r14_3e04.pdf","tr":true,"items":[{"t":"case","label":"American Atheists, Inc. v. Port Auth. of N.Y. & N.J.","cite":"760 F.3d 227","y":2014,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/760/227/","by":{"0":"40","3":"19"}},{"t":"case","label":"AnheuserBusch, Inc. v. Miller (In re Stadium Mgmt. Corp.)","cite":"895 F.2d 845","y":1990,"court":"1st Cir.","url":"https://www.courtlistener.com/c/F.2d/895/845/","by":{"0":"46"}},{"t":"case","label":"Arbaugh v. Y & H Corp.","cite":"546 U.S. 500","y":2006,"id":"2005/04-944","sc":1,"by":{"0":"28, 29","1":"passim","2":"4, 21, 48, 49","3":"15"},"q":[{"src":"brief","b":0,"text":"unfairness and waste of judicial resources.","cite":"546 U.S. at 502"},{"src":"brief","b":1,"text":"made an amountin-controversy threshold an ingredient of subject-matter jurisdiction in delineating diversity-of-citizenship jurisdiction.","cite":"546 U.S. at 514"},{"src":"brief","b":3,"text":"then courts and litigants will be duly instructed and will not be left to wrestle with the issue.","cite":"546 U.S. at 515"},{"src":"opinion","who":"Opinion of the Court (Justice Jackson)","text":"element[s] of a plaintiff's claim for relief.","cite":"546 U. S. 500, 515–516"},{"src":"argument","who":"Ms. Sinzdak","text":"Chief Justice, and may it please the Court: Section 363(m) is not jurisdictional because nothing in its text suggests that it is, and there is no other evidence that satisfies the clear statement rule described in Arbaugh."}]},{"t":"case","label":"Bell v. Hood","cite":"327 U.S. 678","y":1946,"id":"scdb/1945-042","sc":1,"by":{"0":"29","1":"12"}},{"t":"case","label":"Biden v. Texas","cite":"142 S. Ct. 2528","y":2022,"id":"2021/21-954","sc":1,"by":{"0":"18, 28, 29","1":"13, 18"},"q":[{"src":"brief","b":1,"text":"jurisdiction or authority to grant a particular form of relief.","cite":"142 S. Ct. 2528, 2539"},{"src":"brief","b":1,"text":"jurisdiction to grant a particular remedy.","cite":"142 S. Ct. at 2540"}]},{"t":"case","label":"Boechler, P.C. v. Commissioner","cite":"142 S. Ct. 1493","y":2022,"id":"2021/20-1472","sc":1,"by":{"0":"23","1":"passim","2":"4, 21, 37","3":"13, 14"},"q":[{"src":"brief","b":0,"text":"[j]urisdictional requirements * * * must be raised by courts sua sponte.","cite":"142 S. Ct. 1493, 1497"},{"src":"brief","b":1,"text":"mark[s] the bounds of a ‘court’s adjudicatory authority,’","cite":"142 S. Ct. 1493, 1497"},{"src":"brief","b":1,"text":"as a clear indication that a requirement is jurisdictional,","cite":"142 S. Ct. at 1500"},{"src":"brief","b":3,"text":"‘to bring some discipline’ to the use","cite":"142 S. Ct. at 1497"},{"src":"argument","who":"Mr. Brunstad","text":"And in Boechler, this Court said we look at the traditional tools of statutory interpretation. We look at the text, the context, and the history."}]},{"t":"case","label":"Brown v. Ellmann (In re Brown)","cite":"851 F.3d 619","y":2017,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.3d/851/619/","by":{"0":"37, 47"},"q":[{"src":"brief","b":0,"text":"redistributing the proceeds from such a sale,","cite":"851 F.3d at 623"}]},{"t":"case","label":"Castro v. United States","cite":"540 U.S. 375","y":2003,"id":"2003/02-6683","sc":1,"by":{"0":"43, 47"},"q":[{"src":"brief","b":0,"text":"the basic principle that we ‘read limitations on our jurisdiction to review narrowly.’","cite":"540 U.S. 375, 381"}]},{"t":"case","label":"Clear Channel Outdoor, Inc. v. Knupfer (In re PW, LLC)","cite":"391 B.R. 25","y":2008,"court":"B.A.P. 9th Cir.","url":"https://www.courtlistener.com/c/B.R./391/25/","by":{"0":"45"},"q":[{"src":"brief","b":0,"text":"cannot mask an improper condition of the transfer—avoiding appellate review—by cloaking it as an essential and inseparable part of a sale,","cite":"391 B.R. 25, 36-37"}]},{"t":"case","label":"Cohens v. Virginia","cite":"19 U.S. 264","y":1821,"id":"1789-1850/19us264","sc":1,"by":{"0":"20"}},{"t":"case","label":"Colorado River Water Conservation Dist. v. United States","cite":"424 U.S. 800","y":1976,"id":"1975/74-940","sc":1,"by":{"0":"20, 25, 36"},"q":[{"src":"brief","b":0,"text":"virtually unflagging obligation * * * to exercise the jurisdiction given them [by Congress].","cite":"424 U.S. 800, 817"}]},{"t":"case","label":"Contrarian Funds LLC v. Aretex LLC (In re WestPoint Stevens, Inc.)","cite":"600 F.3d 231","y":2010,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/600/231/","by":{"0":"15, 30, 38"},"q":[{"src":"brief","b":0,"text":"bar[] appellate review of any sale authorized by 11 U.S.C. § 363(b) . . . so long as the sale was made to a good-faith purchaser and was not stayed pending appeal.","cite":"600 F.3d at 247"}]},{"t":"case","label":"D.A.N. Joint Venture v. Cacioli (In re Cacioli)","cite":"463 F.3d 229","y":2006,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/463/229/","by":{"0":"41"}},{"t":"case","label":"Davis v. Passman","cite":"442 U.S. 228","y":1979,"id":"1978/78-5072","sc":1,"by":{"0":"28","3":"15"},"q":[{"src":"brief","b":0,"text":"relief is a question of the various remedies a federal court may make available.","cite":"442 U.S. 228, 239, n.18"},{"src":"brief","b":3,"text":"relief is a question of the various remedies a federal court may make available.","cite":"442 U.S. 228, 239 n.18"}]},{"t":"case","label":"Day v. McDonough","cite":"547 U.S. 198","y":2006,"id":"2005/04-1324","sc":1,"by":{"0":"39","1":"26"}},{"t":"case","label":"VII Cases—Continued: Department of Homeland Sec. v. MacLean","cite":"574 U.S. 383","y":2015,"id":"2014/13-894","sc":1,"by":{"0":"34"}},{"t":"case","label":"Dodd v. United States","cite":"545 U.S. 353","y":2005,"id":"2004/04-5286","sc":1,"by":{"0":"27"}},{"t":"case","label":"Eberhart v. United States","cite":"546 U.S. 12","y":2005,"id":"2005/04-9949","sc":1,"by":{"0":"41","3":"19"}},{"t":"case","label":"Exxon Shipping Co. v. Baker","cite":"554 U.S. 471","y":2008,"id":"2007/07-219","sc":1,"by":{"0":"22"}},{"t":"case","label":"Henderson ex rel. Henderson v. Shinseki","cite":"562 U.S. 428","y":2011,"id":"2010/09-1036","sc":1,"by":{"0":"passim","1":"23","3":"13"},"q":[{"src":"brief","b":0,"text":"provides no clear indication that Congress wanted that provision to be treated as having jurisdictional attributes.","cite":"562 U.S. 428, 439"},{"src":"brief","b":0,"text":"alters the normal operation of our adversarial system.","cite":"562 U.S. at 434"},{"src":"brief","b":1,"text":"century’s worth of precedent and practice in American courts","cite":"562 U.S. 428, 436"},{"src":"opinion","who":"Opinion of the Court (Justice Jackson)","text":"certain procedural steps at certain specifed times","cite":"562 U. S., at 435"}]},{"t":"case","label":"Holland v. Florida","cite":"560 U.S. 631","y":2010,"id":"2009/09-5327","sc":1,"by":{"0":"38","3":"18"}},{"t":"case","label":"Kontrick v. Ryan","cite":"540 U.S. 443","y":2004,"id":"2003/02-819","sc":1,"by":{"0":"20, 41","1":"12, 16, 24, 26","2":"37"},"q":[{"src":"brief","b":1,"text":"[o]nly Congress may determine a lower federal court’s subject-matter jurisdiction.","cite":"540 U.S. at 452"}]},{"t":"case","label":"Licensing by Paolo, Inc. v. Sinatra (In re Gucci)","cite":"105 F.3d 837","y":1996,"court":"S.D.N.Y.","url":"https://www.courtlistener.com/c/F.3d/105/837/","by":{"0":"15, 30, 31, 38"}},{"t":"case","label":"New Hampshire v. Maine","cite":"532 U.S. 742","y":2001,"id":"2000/130_orig","sc":1,"by":{"0":"41, 42","3":"20"},"q":[{"src":"brief","b":0,"text":"derive an unfair advantage or impose an unfair detriment on the opposing party if not estopped.","cite":"532 U.S. 742, 750-751"},{"src":"brief","b":0,"text":"deriv[ing] an unfair advantage or impos[ing] an unfair detriment","cite":"532 U.S. at 750"},{"src":"brief","b":3,"text":"derive an unfair advantage or impose an unfair detriment on the opposing party if not estopped.","cite":"532 U.S. 742, 750-751"}]},{"t":"case","label":"Newco Energy v. Energytec, Inc. (In re Energytec, Inc.)","cite":"739 F.3d 215","y":2013,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.3d/739/215/","by":{"0":"49"}},{"t":"case","label":"Official Comm. of Unsecured Creditors v. Trism, Inc. (In re Trism, Inc.)","cite":"328 F.3d 1003","y":2003,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.3d/328/1003/","by":{"0":"46"},"q":[{"src":"brief","b":0,"text":"is so closely linked to the agreement governing the sale that modifying or reversing the provision would adversely alter the parties’ bargained-for exchange.","cite":"328 F.3d 1003, 1007"}]},{"t":"case","label":"Plains Com. Bank v. Long Fam. Land & Cattle Co.","cite":"554 U.S. 316","y":2008,"id":"2007/07-411","sc":1,"by":{"0":"28"},"q":[{"src":"brief","b":0,"text":"A court does not lose jurisdiction over a claim merely because it lacks authority","cite":"554 U.S. 316, 352"}]},{"t":"case","label":"Puckett v. United States","cite":"556 U.S. 129","y":2009,"id":"2008/07-9712","sc":1,"by":{"0":"23"},"q":[{"src":"brief","b":0,"text":"remaining silent about [an] objection and belatedly raising the error only if the case does not conclude in [their] favor.","cite":"556 U.S. 129, 134"}]},{"t":"case","label":"Reed Elsevier, Inc. v. Muchnick","cite":"559 U.S. 154","y":2010,"id":"2009/08-103","sc":1,"by":{"0":"20, 21, 32","1":"15, 17, 22","3":"13, 16, 17"},"q":[{"src":"brief","b":3,"text":"such conditions as jurisdictional, including in statutes other than","cite":"559 U.S. at 168"}]},{"t":"case","label":"Sanchez-Llamas v. Oregon","cite":"548 U.S. 331","y":2006,"id":"2005/04-10566","sc":1,"by":{"0":"22"},"q":[{"src":"brief","b":0,"text":"relies chiefly on the parties to raise significant issues and present them to the courts in the appropriate manner at the appropriate time for adjudication.","cite":"548 U.S. 331, 356"}]},{"t":"case","label":"Sebelius v. Auburn Reg’l Med. Ctr.","cite":"568 U.S. 145","y":2013,"id":"2012/11-1231","sc":1,"by":{"0":"21, 22, 38","1":"13, 26","3":"13, 14"},"q":[{"src":"brief","b":0,"text":"to ward off profligate use of the term ‘jurisdiction.’","cite":"568 U.S. 145, 153"},{"src":"brief","b":3,"text":"result in a waste of adjudicatory resources.","cite":"568 U.S. at 153"}]},{"t":"case","label":"Sioux Honey Ass’n v. Hartford Fire Ins.","cite":"672 F.3d 1041","y":2012,"court":"Fed. Cir.","url":"https://www.courtlistener.com/c/F.3d/672/1041/","by":{"0":"29"}},{"t":"case","label":"Sprint Commc’ns., Inc. v. Jacobs","cite":"571 U.S. 69","y":2013,"id":"2013/12-815","sc":1,"by":{"0":"20"}},{"t":"case","label":"Steel Co. v. Citizens for a Better Env’t","cite":"523 U.S. 83","y":1998,"id":"1997/96-643","sc":1,"by":{"0":"21, 28","1":"passim","2":"47, 48"},"q":[{"src":"argument","who":"Ms. Sinzdak","text":"We think that Steel Co. squarely addresses this at page 96, where the Court explained that a statutory restriction on relief, the question doesn't usually affect jurisdiction because the question under the redressability analysis is not whether a party is entitled to the relief that it's seeking but, rather, whether, if they are able to obtain that relief, it will truly redress their -- their injury."}]},{"t":"case","label":"Trinity 83 Dev., LLC v. ColFin Midwest Funding, LLC","cite":"917 F.3d 599","y":2019,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/917/599/","by":{"0":"31, 37, 38, 47","1":"19","2":"47"}},{"t":"case","label":"United States v. Kwai Fun Wong","cite":"575 U.S. 402","y":2015,"id":"2014/13-1074","sc":1,"by":{"0":"21, 32","1":"9, 14, 17, 19","3":"13"},"q":[{"src":"brief","b":0,"text":"would thus disregard the structural divide built into the statute[s].","cite":"575 U.S. at 412"},{"src":"brief","b":1,"text":"traditional tools of statutory construction must plainly show that","cite":"575 U.S. 402, 409-410"}]},{"t":"case","label":"United States v. Marshall","cite":"954 F.3d 823","y":2020,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.3d/954/823/","by":{"0":"31"}},{"t":"case","label":"United States v. Mezzanatto","cite":"513 U.S. 196","y":1995,"id":"1994/93-1340","sc":1,"by":{"0":"39"},"q":[{"src":"brief","b":0,"text":"statutory provisions are subject to waiver by voluntary agreement of the parties.","cite":"513 U.S. 196, 201"}]},{"t":"case","label":"Williams v. Taylor","cite":"529 U.S. 362","y":2000,"id":"1999/98-8384","sc":1,"by":{"0":"28"}},{"t":"case","label":"Winnett v. Caterpillar, Inc.","cite":"553 F.3d 1000","y":2009,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.3d/553/1000/","by":{"0":"31"}},{"t":"case","label":"Zipes v. Trans World Airlines, Inc.","cite":"455 U.S. 385","y":1982,"id":"1981/78-1545","sc":1,"by":{"0":"26","1":"17","3":"18"},"q":[{"src":"brief","b":0,"text":"does not speak in jurisdictional terms or refer in any way to the jurisdiction of the district courts.","cite":"455 U.S. 385, 394"}]},{"t":"usc","label":"11 U.S.C. § 101","url":"https://www.law.cornell.edu/uscode/text/11/101","subs":["(54)"],"stext":{"head":"§101. Definitions","paras":[[0,"In this title the following definitions shall apply:"],[1,"(1) The term \"accountant\" means accountant authorized under applicable law to practice public accounting, and includes professional accounting association, corporation, or partnership, if so authorized."],[1,"(2) The term \"affiliate\" means—"],[2,"(A) entity that directly or indirectly owns, controls, or holds with power to vote, 20 percent or more of the outstanding voting securities of the debtor, other than an entity that holds such securities—"],[3,"(i) in a fiduciary or agency capacity without sole discretionary power to vote such securities; or"],[3,"(ii) solely to secure a debt, if such entity has not in fact exercised such power to vote;"],[2,"(B) corporation 20 percent or more of whose outstanding voting securities are directly or indirectly owned, controlled, or held with power to vote, by the debtor, or by an entity that directly or indirectly owns, controls, or holds with power to vote, 20 percent or more of the outstanding voting securities of the debtor, other than an entity that holds such securities—"],[3,"(i) in a fiduciary or agency capacity without sole discretionary power to vote such securities; or"],[3,"(ii) solely to secure a debt, if such entity has not in fact exercised such power to vote;"],[2,"(C) person whose business is operated under a lease or operating agreement by a debtor, or person substantially all of whose property is operated under an operating agreement with the debtor; or"],[2,"(D) entity that operates the business or substantially all of the property of the debtor under a lease or operating agreement."],[1,"(3) The term \"assisted person\" means any person whose debts consist primarily of consumer debts and the value of whose nonexempt property is less than $150,000.1"],[1,"(4) The term \"attorney\" means attorney, professional law association, corporation, or partnership, authorized under applicable law to practice law."],[1,"(4A) The term \"bankruptcy assistance\" means any goods or services sold or otherwise provided to an assisted person with the express or implied purpose of providing information, advice, counsel, document preparation, or filing, or attendance at a creditors' meeting or appearing in a case or proceeding on behalf of another or providing legal representation with respect to a case or proceeding under this title."],[1,"(5) The term \"claim\" means—"],[2,"(A) right to payment, whether or not such right is reduced to judgment, liquidated, unliquidated, fixed, contingent, matured, unmatured, disputed, undisputed, legal, equitable, secured, or unsecured; or"],[2,"(B) right to an equitable remedy for breach of performance if such breach gives rise to a right to payment, whether or not such right to an equitable remedy is reduced to judgment, fixed, contingent, matured, unmatured, disputed, undisputed, secured, or unsecured."],[1,"(6) The term \"commodity broker\" means futures commission merchant, foreign futures commission merchant, clearing organization, leverage transaction merchant, or commodity options dealer, as defined in section 761 of this title, with respect to which there is a customer, as defined in section 761 of this title."],[1,"(7) The term \"community claim\" means claim that arose before the commencement of the case concerning the debtor for which property of the kind specified in section 541(a)(2) of this title is liable, whether or not there is any such property at the time of the commencement of the case."],[1,"(7A) The term \"commercial fishing operation\" means—"],[2,"(A) the catching or harvesting of fish, shrimp, lobsters, urchins, seaweed, shellfish, or other aquatic species or products of such species; or"],[2,"(B) for purposes of section 109 and chapter 12, aquaculture activities consisting of raising for market any species or product described in subparagraph (A)."],[1,"(7B) The term \"commercial fishing vessel\" means a vessel used by a family fisherman to carry out a commercial fishing operation."],[1,"(8) The term \"consumer debt\" means debt incurred by an individual primarily for a personal, family, or household purpose."],[1,"(9) The term \"corporation\"—"],[2,"(A) includes—"],[3,"(i) association having a power or privilege that a private corporation, but not an individual or a partnership, possesses;"],[3,"(ii) partnership association organized under a law that makes only the capital subscribed responsible for the debts of such association;"],[3,"(iii) joint-stock company;"],[3,"(iv) unincorporated company or association; or"],[3,"(v) business trust; but"],[2,"(B) does not include limited partnership."],[1,"(10) The term \"creditor\" means—"],[2,"(A) entity that has a claim against the debtor that arose at the time of or before the order for relief concerning the debtor;"],[2,"(B) entity that has a claim against the estate of a kind specified in section 348(d), 502(f), 502(g), 502(h) or 502(i) of this title; or"],[2,"(C) entity that has a community claim."],[1,"(10A) The term \"current monthly income\"—"],[2,"(A) means the average monthly income from all sources that the debtor receives (or in a joint case the debtor and the debtor's spouse receive) without regard to whether such income is taxable income, derived during the 6-month period ending on—"],[3,"(i) the last day of the calendar month immediately preceding the date of the commencement of the case if the debtor files the schedule of current income required by section 521(a)(1)(B)(ii); or"],[3,"(ii) the date on which current income is determined by the court for purposes of this title if the debtor does not file the schedule of current income required by section 521(a)(1)(B)(ii); and"],[2,"(B)(i) includes any amount paid by any entity other than the debtor (or in a joint case the debtor and the debtor's spouse), on a regular basis for the household expenses of the debtor or the debtor's dependents (and in a joint case the debtor's spouse if not otherwise a dependent); and"],[2,"(ii) excludes—"],[3,"(I) benefits received under the Social Security Act (42 U.S.C. 301 et seq.);"],[3,"(II) payments to victims of war crimes or crimes against humanity on account of their status as victims of such crimes;"],[3,"(III) payments to victims of international terrorism or domestic terrorism, as those terms are defined in section 2331 of title 18, on account of their status as victims of such terrorism; and"],[3,"(IV) any monthly compensation, pension, pay, annuity, or allowance paid under title 10, 37, or 38 in connection with a disability, combat-related injury or disability, or death of a member of the uniformed services, except that any retired pay excluded under this subclause shall include retired pay paid under chapter 61 of title 10 only to the extent that such retired pay exceeds the amount of retired pay to which the debtor would otherwise be entitled if retired under any provision of title 10 other than chapter 61 of that title."],[1,"(11) The term \"custodian\" means—"],[2,"(A) receiver or trustee of any of the property of the debtor, appointed in a case or proceeding not under this title;"],[2,"(B) assignee under a general assignment for the benefit of the debtor's creditors; or"],[2,"(C) trustee, receiver, or agent under applicable law, or under a contract, that is appointed or authorized to take charge of property of the debtor for the purpose of enforcing a lien against such property, or for the purpose of general administration of such property for the benefit of the debtor's creditors."],[1,"(12) The term \"debt\" means liability on a claim."],[1,"(12A) The term \"debt relief agency\" means any person who provides any bankruptcy assistance to an assisted person in return for the payment of money or other valuable consideration, or who is a bankruptcy petition preparer under section 110, but does not include—"],[2,"(A) any person who is an officer, director, employee, or agent of a person who provides such assistance or of the bankruptcy petition preparer;"],[2,"(B) a nonprofit organization that is exempt from taxation under section 501(c)(3) of the Internal Revenue Code of 1986;"],[2,"(C) a creditor of such assisted person, to the extent that the creditor is assisting such assisted person to restructure any debt owed by such assisted person to the creditor;"],[2,"(D) a depository institution (as defined in section 3 of the Federal Deposit Insurance Act) or any Federal credit union or State credit union (as those terms are defined in section 101 of the Federal Credit Union Act), or any affiliate or subsidiary of such depository institution or credit union; or"],[2,"(E) an author, publisher, distributor, or seller of works subject to copyright protection under title 17, when acting in such capacity."],[1,"(13) The term \"debtor\" means person or municipality concerning which a case under this title has been commenced."],[1,"(13A) The term \"debtor's principal residence\"—"],[2,"(A) means a residential structure if used as the principal residence by the debtor, including incidental property, without regard to whether that structure is attached to real property; and"],[2,"(B) includes an individual condominium or cooperative unit, a mobile or manufactured home, or trailer if used as the principal residence by the debtor."],[1,"(14) The term \"disinterested person\" means a person that—"],[2,"(A) is not a creditor, an equity security holder, or an insider;"],[2,"(B) is not and was not, within 2 years before the date of the filing of the petition, a director, officer, or employee of the debtor; and"]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/11/101?type=usc&year=mostrecent&link-type=html"},"by":{"0":"passim","1":"17","2":"8","3":"21, 22, 23"}},{"t":"usc","label":"11 U.S.C. § 363","url":"https://www.law.cornell.edu/uscode/text/11/363","subs":["(b)","(c)","(m)","(b)(1)","(c)(2)(B)","(c)(1)","(f)","(l)","(n)"],"stext":{"head":"§363. Use, sale, or lease of property","paras":[[0,"(a) In this section, \"cash collateral\" means cash, negotiable instruments, documents of title, securities, deposit accounts, or other cash equivalents whenever acquired in which the estate and an entity other than the estate have an interest and includes the proceeds, products, offspring, rents, or profits of property and the fees, charges, accounts or other payments for the use or occupancy of rooms and other public facilities in hotels, motels, or other lodging properties subject to a security interest as provided in section 552(b) of this title, whether existing before or after the commencement of a case under this title."],[0,"(b)(1) The trustee, after notice and a hearing, may use, sell, or lease, other than in the ordinary course of business, property of the estate, except that if the debtor in connection with offering a product or a service discloses to an individual a policy prohibiting the transfer of personally identifiable information about individuals to persons that are not affiliated with the debtor and if such policy is in effect on the date of the commencement of the case, then the trustee may not sell or lease personally identifiable information to any person unless—"],[1,"(A) such sale or such lease is consistent with such policy; or"],[1,"(B) after appointment of a consumer privacy ombudsman in accordance with section 332, and after notice and a hearing, the court approves such sale or such lease—"],[2,"(i) giving due consideration to the facts, circumstances, and conditions of such sale or such lease; and"],[2,"(ii) finding that no showing was made that such sale or such lease would violate applicable nonbankruptcy law."],[0,"(2) If notification is required under subsection (a) of section 7A of the Clayton Act in the case of a transaction under this subsection, then—"],[1,"(A) notwithstanding subsection (a) of such section, the notification required by such subsection to be given by the debtor shall be given by the trustee; and"],[1,"(B) notwithstanding subsection (b) of such section, the required waiting period shall end on the 15th day after the date of the receipt, by the Federal Trade Commission and the Assistant Attorney General in charge of the Antitrust Division of the Department of Justice, of the notification required under such subsection (a), unless such waiting period is extended—"],[2,"(i) pursuant to subsection (e)(2) of such section, in the same manner as such subsection (e)(2) applies to a cash tender offer;"],[2,"(ii) pursuant to subsection (g)(2) of such section; or"],[2,"(iii) by the court after notice and a hearing."],[0,"(c)(1) If the business of the debtor is authorized to be operated under section 721, 1108, 1183, 1184, 1203, 1204, or 1304 of this title and unless the court orders otherwise, the trustee may enter into transactions, including the sale or lease of property of the estate, in the ordinary course of business, without notice or a hearing, and may use property of the estate in the ordinary course of business without notice or a hearing."],[0,"(2) The trustee may not use, sell, or lease cash collateral under paragraph (1) of this subsection unless—"],[1,"(A) each entity that has an interest in such cash collateral consents; or"],[1,"(B) the court, after notice and a hearing, authorizes such use, sale, or lease in accordance with the provisions of this section."],[0,"(3) Any hearing under paragraph (2)(B) of this subsection may be a preliminary hearing or may be consolidated with a hearing under subsection (e) of this section, but shall be scheduled in accordance with the needs of the debtor. If the hearing under paragraph (2)(B) of this subsection is a preliminary hearing, the court may authorize such use, sale, or lease only if there is a reasonable likelihood that the trustee will prevail at the final hearing under subsection (e) of this section. The court shall act promptly on any request for authorization under paragraph (2)(B) of this subsection."],[0,"(4) Except as provided in paragraph (2) of this subsection, the trustee shall segregate and account for any cash collateral in the trustee's possession, custody, or control."],[0,"(d) The trustee may use, sell, or lease property under subsection (b) or (c) of this section—"],[1,"(1) in the case of a debtor that is a corporation or trust that is not a moneyed business, commercial corporation, or trust, only in accordance with nonbankruptcy law applicable to the transfer of property by a debtor that is such a corporation or trust; and"],[1,"(2) only to the extent not inconsistent with any relief granted under subsection (c), (d), (e), or (f) of section 362."],[0,"(e) Notwithstanding any other provision of this section, at any time, on request of an entity that has an interest in property used, sold, or leased, or proposed to be used, sold, or leased, by the trustee, the court, with or without a hearing, shall prohibit or condition such use, sale, or lease as is necessary to provide adequate protection of such interest. This subsection also applies to property that is subject to any unexpired lease of personal property (to the exclusion of such property being subject to an order to grant relief from the stay under section 362)."],[0,"(f) The trustee may sell property under subsection (b) or (c) of this section free and clear of any interest in such property of an entity other than the estate, only if—"],[1,"(1) applicable nonbankruptcy law permits sale of such property free and clear of such interest;"],[1,"(2) such entity consents;"],[1,"(3) such interest is a lien and the price at which such property is to be sold is greater than the aggregate value of all liens on such property;"],[1,"(4) such interest is in bona fide dispute; or"],[1,"(5) such entity could be compelled, in a legal or equitable proceeding, to accept a money satisfaction of such interest."],[0,"(g) Notwithstanding subsection (f) of this section, the trustee may sell property under subsection (b) or (c) of this section free and clear of any vested or contingent right in the nature of dower or curtesy."],[0,"(h) Notwithstanding subsection (f) of this section, the trustee may sell both the estate's interest, under subsection (b) or (c) of this section, and the interest of any co-owner in property in which the debtor had, at the time of the commencement of the case, an undivided interest as a tenant in common, joint tenant, or tenant by the entirety, only if—"],[1,"(1) partition in kind of such property among the estate and such co-owners is impracticable;"],[1,"(2) sale of the estate's undivided interest in such property would realize significantly less for the estate than sale of such property free of the interests of such co-owners;"],[1,"(3) the benefit to the estate of a sale of such property free of the interests of co-owners outweighs the detriment, if any, to such co-owners; and"],[1,"(4) such property is not used in the production, transmission, or distribution, for sale, of electric energy or of natural or synthetic gas for heat, light, or power."],[0,"(i) Before the consummation of a sale of property to which subsection (g) or (h) of this section applies, or of property of the estate that was community property of the debtor and the debtor's spouse immediately before the commencement of the case, the debtor's spouse, or a co-owner of such property, as the case may be, may purchase such property at the price at which such sale is to be consummated."],[0,"(j) After a sale of property to which subsection (g) or (h) of this section applies, the trustee shall distribute to the debtor's spouse or the co-owners of such property, as the case may be, and to the estate, the proceeds of such sale, less the costs and expenses, not including any compensation of the trustee, of such sale, according to the interests of such spouse or co-owners, and of the estate."],[0,"(k) At a sale under subsection (b) of this section of property that is subject to a lien that secures an allowed claim, unless the court for cause orders otherwise the holder of such claim may bid at such sale, and, if the holder of such claim purchases such property, such holder may offset such claim against the purchase price of such property."],[0,"(l) Subject to the provisions of section 365, the trustee may use, sell, or lease property under subsection (b) or (c) of this section, or a plan under chapter 11, 12, or 13 of this title may provide for the use, sale, or lease of property, notwithstanding any provision in a contract, a lease, or applicable law that is conditioned on the insolvency or financial condition of the debtor, on the commencement of a case under this title concerning the debtor, or on the appointment of or the taking possession by a trustee in a case under this title or a custodian, and that effects, or gives an option to effect, a forfeiture, modification, or termination of the debtor's interest in such property."],[0,"(m) The reversal or modification on appeal of an authorization under subsection (b) or (c) of this section of a sale or lease of property does not affect the validity of a sale or lease under such authorization to an entity that purchased or leased such property in good faith, whether or not such entity knew of the pendency of the appeal, unless such authorization and such sale or lease were stayed pending appeal."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/11/363?type=usc&year=mostrecent&link-type=html"},"by":{"0":"passim, passim, passim, passim","1":"2, passim, 2, passim, 2, passim","2":"passim, passim, passim, 6, 25, 33, passim, 7, 34, 35, passim, 12, 26, 27, 28","3":"21, 22, 23, 3, 22, 3, 22, passim, 11"},"q":[{"src":"brief","b":0,"text":"[t]he reversal or modification on appeal of any authorization under subsection (b) or (c) of this section of a sale or lease of property.","cite":"11 U.S.C. 363(m)"},{"src":"brief","b":1,"text":"to an entity that purchased or leased [the] property in good faith.","cite":"11 U.S.C. 363(m)"},{"src":"brief","b":1,"text":"knew of the pendency of the appeal,","cite":"11 U.S.C. 363(m)"},{"src":"brief","b":3,"text":"appeal of an authorization under subsections (b) or (c)","cite":"11 U.S.C. 363(m)"},{"src":"argument","who":"Mr. Brunstad","text":"The sale was under Section 363 of the assets, which required further approval of the Court for the transfer of the lease, which is also part of the sale, for which additional consideration was paid in addition to the 1.4 billion that was paid for the bulk sale."},{"src":"argument","who":"Mr. Brunstad","text":"There is a specific provision of Section 363 that allows for overturning a sale to bad faith purchasers, 363(n). That remedial scheme would make no sense if there was also some vague general equitable power of the bankruptcy court to simply do an end run around the avoidance powers and simply bring property back into the estate."},{"src":"argument","who":"Mr. Brunstad","text":"Jurisdiction is not relief. There must be some tangible remedy that they must be able to get. They cannot. Wholly apart from Section 363 --"}]},{"t":"usc","label":"11 U.S.C. § 365","url":"https://www.law.cornell.edu/uscode/text/11/365","subs":["(b)","(b)(3)","(b)(3)(A)","(a)","(b)(2)","(f)","(f)(2)","(f)(2)(A)","(k)","(b)(1)","(d)(4)"],"stext":{"head":"§365. Executory contracts and unexpired leases","paras":[[0,"(a) Except as provided in sections 765 and 766 of this title and in subsections (b), (c), and (d) of this section, the trustee, subject to the court's approval, may assume or reject any executory contract or unexpired lease of the debtor."],[0,"(b)(1) If there has been a default in an executory contract or unexpired lease of the debtor, the trustee may not assume such contract or lease unless, at the time of assumption of such contract or lease, the trustee—"],[1,"(A) cures, or provides adequate assurance that the trustee will promptly cure, such default other than a default that is a breach of a provision relating to the satisfaction of any provision (other than a penalty rate or penalty provision) relating to a default arising from any failure to perform nonmonetary obligations under an unexpired lease of real property, if it is impossible for the trustee to cure such default by performing nonmonetary acts at and after the time of assumption, except that if such default arises from a failure to operate in accordance with a nonresidential real property lease, then such default shall be cured by performance at and after the time of assumption in accordance with such lease, and pecuniary losses resulting from such default shall be compensated in accordance with the provisions of this paragraph;"],[1,"(B) compensates, or provides adequate assurance that the trustee will promptly compensate, a party other than the debtor to such contract or lease, for any actual pecuniary loss to such party resulting from such default; and"],[1,"(C) provides adequate assurance of future performance under such contract or lease."],[0,"(2) Paragraph (1) of this subsection does not apply to a default that is a breach of a provision relating to—"],[1,"(A) the insolvency or financial condition of the debtor at any time before the closing of the case;"],[1,"(B) the commencement of a case under this title;"],[1,"(C) the appointment of or taking possession by a trustee in a case under this title or a custodian before such commencement; or"],[1,"(D) the satisfaction of any penalty rate or penalty provision relating to a default arising from any failure by the debtor to perform nonmonetary obligations under the executory contract or unexpired lease."],[0,"(3) For the purposes of paragraph (1) of this subsection and paragraph (2)(B) of subsection (f), adequate assurance of future performance of a lease of real property in a shopping center includes adequate assurance—"],[1,"(A) of the source of rent and other consideration due under such lease, and in the case of an assignment, that the financial condition and operating performance of the proposed assignee and its guarantors, if any, shall be similar to the financial condition and operating performance of the debtor and its guarantors, if any, as of the time the debtor became the lessee under the lease;"],[1,"(B) that any percentage rent due under such lease will not decline substantially;"],[1,"(C) that assumption or assignment of such lease is subject to all the provisions thereof, including (but not limited to) provisions such as a radius, location, use, or exclusivity provision, and will not breach any such provision contained in any other lease, financing agreement, or master agreement relating to such shopping center; and"],[1,"(D) that assumption or assignment of such lease will not disrupt any tenant mix or balance in such shopping center."],[0,"(4) Notwithstanding any other provision of this section, if there has been a default in an unexpired lease of the debtor, other than a default of a kind specified in paragraph (2) of this subsection, the trustee may not require a lessor to provide services or supplies incidental to such lease before assumption of such lease unless the lessor is compensated under the terms of such lease for any services and supplies provided under such lease before assumption of such lease."],[0,"(c) The trustee may not assume or assign any executory contract or unexpired lease of the debtor, whether or not such contract or lease prohibits or restricts assignment of rights or delegation of duties, if—"],[1,"(1)(A) applicable law excuses a party, other than the debtor, to such contract or lease from accepting performance from or rendering performance to an entity other than the debtor or the debtor in possession, whether or not such contract or lease prohibits or restricts assignment of rights or delegation of duties; and"],[1,"(B) such party does not consent to such assumption or assignment; or"],[1,"(2) such contract is a contract to make a loan, or extend other debt financing or financial accommodations, to or for the benefit of the debtor, or to issue a security of the debtor; or"],[1,"(3) such lease is of nonresidential real property and has been terminated under applicable nonbankruptcy law prior to the order for relief."],[0,"(d)(1) In a case under chapter 7 of this title, if the trustee does not assume or reject an executory contract or unexpired lease of residential real property or of personal property of the debtor within 60 days after the order for relief, or within such additional time as the court, for cause, within such 60-day period, fixes, then such contract or lease is deemed rejected."],[0,"(2) In a case under chapter 9, 11, 12, or 13 of this title, the trustee may assume or reject an executory contract or unexpired lease of residential real property or of personal property of the debtor at any time before the confirmation of a plan but the court, on the request of any party to such contract or lease, may order the trustee to determine within a specified period of time whether to assume or reject such contract or lease."],[0,"(3) The trustee shall timely perform all the obligations of the debtor, except those specified in section 365(b)(2), arising from and after the order for relief under any unexpired lease of nonresidential real property, until such lease is assumed or rejected, notwithstanding section 503(b)(1) of this title. The court may extend, for cause, the time for performance of any such obligation that arises within 60 days after the date of the order for relief, but the time for performance shall not be extended beyond such 60-day period. This subsection shall not be deemed to affect the trustee's obligations under the provisions of subsection (b) or (f) of this section. Acceptance of any such performance does not constitute waiver or relinquishment of the lessor's rights under such lease or under this title."],[0,"(4)(A) Subject to subparagraph (B), an unexpired lease of nonresidential real property under which the debtor is the lessee shall be deemed rejected, and the trustee shall immediately surrender that nonresidential real property to the lessor, if the trustee does not assume or reject the unexpired lease by the earlier of—"],[1,"(i) the date that is 120 days after the date of the order for relief; or"],[1,"(ii) the date of the entry of an order confirming a plan."],[0,"(B)(i) The court may extend the period determined under subparagraph (A), prior to the expiration of the 120-day period, for 90 days on the motion of the trustee or lessor for cause."],[0,"(ii) If the court grants an extension under clause (i), the court may grant a subsequent extension only upon prior written consent of the lessor in each instance."],[0,"(5) The trustee shall timely perform all of the obligations of the debtor, except those specified in section 365(b)(2), first arising from or after 60 days after the order for relief in a case under chapter 11 of this title under an unexpired lease of personal property (other than personal property leased to an individual primarily for personal, family, or household purposes), until such lease is assumed or rejected notwithstanding section 503(b)(1) of this title, unless the court, after notice and a hearing and based on the equities of the case, orders otherwise with respect to the obligations or timely performance thereof. This subsection shall not be deemed to affect the trustee's obligations under the provisions of subsection (b) or (f). Acceptance of any such performance does not constitute waiver or relinquishment of the lessor's rights under such lease or under this title."],[0,"(e)(1) Notwithstanding a provision in an executory contract or unexpired lease, or in applicable law, an executory contract or unexpired lease of the debtor may not be terminated or modified, and any right or obligation under such contract or lease may not be terminated or modified, at any time after the commencement of the case solely because of a provision in such contract or lease that is conditioned on—"],[1,"(A) the insolvency or financial condition of the debtor at any time before the closing of the case;"],[1,"(B) the commencement of a case under this title; or"],[1,"(C) the appointment of or taking possession by a trustee in a case under this title or a custodian before such commencement."],[0,"(2) Paragraph (1) of this subsection does not apply to an executory contract or unexpired lease of the debtor, whether or not such contract or lease prohibits or restricts assignment of rights or delegation of duties, if—"],[1,"(A)(i) applicable law excuses a party, other than the debtor, to such contract or lease from accepting performance from or rendering performance to the trustee or to an assignee of such contract or lease, whether or not such contract or lease prohibits or restricts assignment of rights or delegation of duties; and"]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/11/365?type=usc&year=mostrecent&link-type=html"},"by":{"0":"passim, 44, 48, 9, 11, 11","1":"2, 4, 7, 2, 2, 5, 6, 2, 2","2":"passim, 34, 34, 35, 7, 13, 17, 18, 33, 7, 8, 34, 35, 7, 32, 34, 14","3":"3, 23, 12, 11, 12, 24, 22, 24, 12"},"q":[{"src":"brief","b":1,"text":"trustee, subject to the court’s approval, may assume","cite":"11 U.S.C. 365(a)"},{"src":"brief","b":1,"text":"lease of real property in a shopping center.","cite":"11 U.S.C. 365(b)(3)"},{"src":"argument","who":"Mr. Hallward-Driemeier","text":"Rather, the order authorized assumption and assignment of a lease under Section 365, with no additional payment to the debtor. It does not defeat any congressional limit on the Court's power to hold Transform to the position it took in the bankruptcy court."},{"src":"argument","who":"Mr. Hallward-Driemeier","text":"There's a -- a lease that was given to Sears, and there's a second piece of paper that says, pursuant to authority under Section 365 of the bankruptcy court -- code, the -- the -- Sears' lease has been assigned to Transform, but when on remand that order is taken away, then Transform has nothing to -- to assert in terms of its right to the -- to the leasehold in -- at Mall of America."},{"src":"argument","who":"Mr. Brunstad","text":"-- of Section 365 of the Bankruptcy Code. There is no such thing. It would be an implied cause of action that does not exist. So they are foreclosed procedurally and substantively from making any claim for damages which they've never heretofore even suggested."}]},{"t":"usc","label":"28 U.S.C. § 157","url":"https://www.law.cornell.edu/uscode/text/28/157","subs":["(b)","(b)(1)","(b)(2)(M)","(b)(2)(N)"],"stext":{"head":"§157. Procedures","paras":[[0,"(a) Each district court may provide that any or all cases under title 11 and any or all proceedings arising under title 11 or arising in or related to a case under title 11 shall be referred to the bankruptcy judges for the district."],[0,"(b)(1) Bankruptcy judges may hear and determine all cases under title 11 and all core proceedings arising under title 11, or arising in a case under title 11, referred under subsection (a) of this section, and may enter appropriate orders and judgments, subject to review under section 158 of this title."],[0,"(2) Core proceedings include, but are not limited to—"],[1,"(A) matters concerning the administration of the estate;"],[1,"(B) allowance or disallowance of claims against the estate or exemptions from property of the estate, and estimation of claims or interests for the purposes of confirming a plan under chapter 11, 12, or 13 of title 11 but not the liquidation or estimation of contingent or unliquidated personal injury tort or wrongful death claims against the estate for purposes of distribution in a case under title 11;"],[1,"(C) counterclaims by the estate against persons filing claims against the estate;"],[1,"(D) orders in respect to obtaining credit;"],[1,"(E) orders to turn over property of the estate;"],[1,"(F) proceedings to determine, avoid, or recover preferences;"],[1,"(G) motions to terminate, annul, or modify the automatic stay;"],[1,"(H) proceedings to determine, avoid, or recover fraudulent conveyances;"],[1,"(I) determinations as to the dischargeability of particular debts;"],[1,"(J) objections to discharges;"],[1,"(K) determinations of the validity, extent, or priority of liens;"],[1,"(L) confirmations of plans;"],[1,"(M) orders approving the use or lease of property, including the use of cash collateral;"],[1,"(N) orders approving the sale of property other than property resulting from claims brought by the estate against persons who have not filed claims against the estate;"],[1,"(O) other proceedings affecting the liquidation of the assets of the estate or the adjustment of the debtor-creditor or the equity security holder relationship, except personal injury tort or wrongful death claims; and"],[1,"(P) recognition of foreign proceedings and other matters under chapter 15 of title 11."],[0,"(3) The bankruptcy judge shall determine, on the judge's own motion or on timely motion of a party, whether a proceeding is a core proceeding under this subsection or is a proceeding that is otherwise related to a case under title 11. A determination that a proceeding is not a core proceeding shall not be made solely on the basis that its resolution may be affected by State law."],[0,"(4) Non-core proceedings under section 157(b)(2)(B) of title 28, United States Code, shall not be subject to the mandatory abstention provisions of section 1334(c)(2)."],[0,"(5) The district court shall order that personal injury tort and wrongful death claims shall be tried in the district court in which the bankruptcy case is pending, or in the district court in the district in which the claim arose, as determined by the district court in which the bankruptcy case is pending."],[0,"(c)(1) A bankruptcy judge may hear a proceeding that is not a core proceeding but that is otherwise related to a case under title 11. In such proceeding, the bankruptcy judge shall submit proposed findings of fact and conclusions of law to the district court, and any final order or judgment shall be entered by the district judge after considering the bankruptcy judge's proposed findings and conclusions and after reviewing de novo those matters to which any party has timely and specifically objected."],[0,"(2) Notwithstanding the provisions of paragraph (1) of this subsection, the district court, with the consent of all the parties to the proceeding, may refer a proceeding related to a case under title 11 to a bankruptcy judge to hear and determine and to enter appropriate orders and judgments, subject to review under section 158 of this title."],[0,"(d) The district court may withdraw, in whole or in part, any case or proceeding referred under this section, on its own motion or on timely motion of any party, for cause shown. The district court shall, on timely motion of a party, so withdraw a proceeding if the court determines that resolution of the proceeding requires consideration of both title 11 and other laws of the United States regulating organizations or activities affecting interstate commerce."],[0,"(e) If the right to a jury trial applies in a proceeding that may be heard under this section by a bankruptcy judge, the bankruptcy judge may conduct the jury trial if specially designated to exercise such jurisdiction by the district court and with the express consent of all the parties."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/28/157?type=usc&year=mostrecent&link-type=html"},"by":{"0":"32, 43, 32, 33","1":"3, 6, 3, 3, 17, 17"},"q":[{"src":"brief","b":1,"text":"subject to review under section 158,","cite":"28 U.S.C. 157(b)(1)"}]},{"t":"usc","label":"28 U.S.C. § 158","url":"https://www.law.cornell.edu/uscode/text/28/158","subs":["(a)","(a)(1)","(a)(2)","(a)(3)","(d)","(d)(1)"],"by":{"0":"passim, 33, 34, 36, 33, 33, 33, 34, 36","1":"3, 16, 17, 3, 16, 16, 3"},"q":[{"src":"brief","b":0,"text":"from final judgments, orders, and decrees * * * of bankruptcy judges entered in cases and proceedings","cite":"28 U.S.C. 158(a)"}]},{"t":"usc","label":"28 U.S.C. § 1334","url":"https://www.law.cornell.edu/uscode/text/28/1334","subs":["(d)","(e)","(a)","(b)"],"stext":{"head":"§1334. Bankruptcy cases and proceedings","paras":[[0,"(a) Except as provided in subsection (b) of this section, the district courts shall have original and exclusive jurisdiction of all cases under title 11."],[0,"(b) Except as provided in subsection (e)(2), and notwithstanding any Act of Congress that confers exclusive jurisdiction on a court or courts other than the district courts, the district courts shall have original but not exclusive jurisdiction of all civil proceedings arising under title 11, or arising in or related to cases under title 11."],[0,"(c)(1) Except with respect to a case under chapter 15 of title 11, nothing in this section prevents a district court in the interest of justice, or in the interest of comity with State courts or respect for State law, from abstaining from hearing a particular proceeding arising under title 11 or arising in or related to a case under title 11."],[0,"(2) Upon timely motion of a party in a proceeding based upon a State law claim or State law cause of action, related to a case under title 11 but not arising under title 11 or arising in a case under title 11, with respect to which an action could not have been commenced in a court of the United States absent jurisdiction under this section, the district court shall abstain from hearing such proceeding if an action is commenced, and can be timely adjudicated, in a State forum of appropriate jurisdiction."],[0,"(d) Any decision to abstain or not to abstain made under subsection (c) (other than a decision not to abstain in a proceeding described in subsection (c)(2)) is not reviewable by appeal or otherwise by the court of appeals under section 158(d), 1291, or 1292 of this title or by the Supreme Court of the United States under section 1254 of this title. Subsection (c) and this subsection shall not be construed to limit the applicability of the stay provided for by section 362 of title 11, United States Code, as such section applies to an action affecting the property of the estate in bankruptcy."],[0,"(e) The district court in which a case under title 11 is commenced or is pending shall have exclusive jurisdiction—"],[1,"(1) of all the property, wherever located, of the debtor as of the commencement of such case, and of property of the estate; and"],[1,"(2) over all claims or causes of action that involve construction of section 327 of title 11, United States Code, or rules relating to disclosure requirements under section 327."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/28/1334?type=usc&year=mostrecent&link-type=html"},"by":{"0":"35","1":"3, 16","2":"passim","3":"4, 5, 4, 5, 4, 5, 4, 5"},"q":[{"src":"brief","b":3,"text":"all civil proceedings arising under title 11, or arising in or related to cases under title 11.","cite":"28 U.S.C. 1334(a)"}]},{"t":"usc","label":"28 U.S.C. § 1441","url":"https://www.law.cornell.edu/uscode/text/28/1441","subs":["(e)(4)"],"by":{"0":"35"}},{"t":"usc","label":"28 U.S.C. § 1447","url":"https://www.law.cornell.edu/uscode/text/28/1447","subs":["(d)"],"by":{"0":"34"},"q":[{"src":"brief","b":0,"text":"[a]n order remanding a case to the State court from which it was removed is not reviewable on appeal or otherwise.","cite":"28 U.S.C. 1447(d)"}]},{"t":"usc","label":"28 U.S.C. § 1452","url":"https://www.law.cornell.edu/uscode/text/28/1452","subs":["(b)"],"by":{"0":"34, 35"},"q":[{"src":"brief","b":0,"text":"[a]n order entered under this subsection remanding a claim or cause of action, or a decision to not remand, is not reviewable by appeal or otherwise by the court of appeals under section 158(d), 1291, or 1292 of this title or by the Supreme Court of the United States under section 1254 of this title.","cite":"28 U.S.C. 1452(b)"}]},{"t":"law","label":"Pub. L. No. 98-353","url":"https://www.govinfo.gov/link/statute/98/333","by":{"0":"11, 32"}},{"t":"const","label":"Article III, Section 1","clauses":[["judicial-vesting","Judicial Vesting Clause"]],"text":"The judicial Power of the United States, shall be vested in one supreme Court, and in such inferior Courts as the Congress may from time to time ordain and establish. The Judges, both of the supreme and inferior Courts, shall hold their Offices during good Behaviour, and shall, at stated Times, receive for their Services, a Compensation, which shall not be diminished during their Continuance in Office.","by":{"0":"20"}},{"t":"case","label":"Arizonans for Official English v. Arizona","cite":"520 U.S. 43","y":1997,"id":"1996/95-974","sc":1,"by":{"1":"11","2":"23"},"q":[{"src":"argument","who":"Mr. Brunstad","text":"In this Court's decision in Official English for Arizonans, the Court said we consider not only our ability to decide the question but the lower court's ability to proceed."}]},{"t":"case","label":"(III) Cases—Continued: Bank of Am. Corp. v. City of Miami","cite":"137 S. Ct. 1296","y":2017,"id":"2016/15-1111","sc":1,"by":{"1":"32"},"q":[{"src":"brief","b":1,"text":"lack[s] the benefit of [the court of appeals’] judgment on how","cite":"137 S. Ct. 1296, 1306"}]},{"t":"case","label":"Bowles v. Russell","cite":"551 U.S. 205","y":2007,"id":"2006/06-5306","sc":1,"by":{"1":"10, 22, 23","2":"passim","3":"15, 16"},"q":[{"src":"brief","b":2,"text":"[b]ecause Congress decides whether federal courts can hear cases at all, it can also determine when, and under what conditions, federal courts can hear them.","cite":"551 U.S. at 212"},{"src":"brief","b":3,"text":"a century’s worth of precedent and practice in American courts.","cite":"551 U.S. at 209 n.2"}]},{"t":"case","label":"Campbell-Ewald Co. v. Gomez","cite":"577 U.S. 153","y":2016,"id":"2015/14-857","sc":1,"by":{"1":"11"},"q":[{"src":"brief","b":1,"text":"action can no longer proceed and must be dismissed as moot.","cite":"577 U.S. 153, 161"}]},{"t":"case","label":"Central Virginia Cmty. College v. Katz","cite":"546 U.S. 356","y":2006,"id":"2005/04-885","sc":1,"by":{"1":"25","2":"2, 9, 42","3":"2, 5"},"q":[{"src":"brief","b":1,"text":"the principal focus of the bankruptcy proceedings is and was always the res, some exercises of bankruptcy courts’ powers * * * unquestionably involve[] more than mere adjudication of rights in a res.","cite":"546 U.S. 356, 362, 378"},{"src":"brief","b":2,"text":"ancillary to and in furtherance of the court’s in rem jurisdiction.","cite":"546 U.S. at 372"}]},{"t":"case","label":"Cinicola v. Scharffenberger","cite":"248 F.3d 110","y":2001,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.3d/248/110/","by":{"1":"29"}},{"t":"case","label":"Connecticut Nat’l Bank v. Germain","cite":"503 U.S. 249","y":1992,"id":"1991/90-1791","sc":1,"by":{"1":"3"}},{"t":"case","label":"Fort Bend County v. Davis","cite":"139 S. Ct. 1843","y":2019,"id":"2018/18-525","sc":1,"by":{"1":"18, 22, 23, 26","3":"13"},"q":[{"src":"brief","b":1,"text":"does not become jurisdictional whenever it ‘promotes important congressional objectives.’","cite":"139 S. Ct. at 1851"},{"src":"brief","b":1,"text":"good reason promptly to raise an objection that may rid them of the","cite":"139 S. Ct. at 1851"}]},{"t":"case","label":"Freshman v. Atkins","cite":"269 U.S. 121","y":1925,"id":"scdb/1925-039","sc":1,"by":{"1":"28"}},{"t":"case","label":"Garland v. Aleman Gonzalez","cite":"142 S. Ct. 2057","y":2022,"id":"2021/20-322","sc":1,"by":{"1":"18"},"q":[{"src":"brief","b":1,"text":"strips lower courts of ‘jurisdiction or authority’ to ‘enjoin or restrain the operation of ’ the relevant statutory provisions,","cite":"142 S. Ct. 2057, 2064"}]},{"t":"case","label":"Hamer v. Neighborhood Hous. Servs.","cite":"138 S. Ct. 13","y":2017,"id":"2017/16-658","sc":1,"by":{"1":"26, 27","3":"13, 19"},"q":[{"src":"brief","b":3,"text":"you’re not going to go to the district and say 363(m) applies here.","cite":"138 S. Ct. at 17 n.1"}]},{"t":"case","label":"Lozman v. City of Riviera Beach","cite":"568 U.S. 115","y":2013,"id":"2012/11-626","sc":1,"by":{"1":"25"}},{"t":"case","label":"Lujan v. Defenders of Wildlife","cite":"504 U.S. 555","y":1992,"id":"1991/90-1424","sc":1,"by":{"1":"8, 11"}},{"t":"case","label":"Nutraceutical Corp. v. Lambert","cite":"139 S. Ct. 710","y":2019,"id":"2018/17-1094","sc":1,"by":{"1":"26"},"q":[{"src":"brief","b":1,"text":"can be waived or forfeited by an opposing party.","cite":"139 S. Ct. 710, 714"}]},{"t":"case","label":"Patchak v. Zinke","cite":"138 S. Ct. 897","y":2018,"id":"2017/16-498","sc":1,"by":{"1":"16"}},{"t":"case","label":"Republic Nat’l Bank v. United States","cite":"506 U.S. 80","y":1992,"id":"1992/91-767","sc":1,"by":{"1":"25","2":"40, 41","3":"passim"},"q":[{"src":"brief","b":3,"text":"h[e]ld that, in an in rem forfeiture action, the Court of Appeals is not divested of jurisdiction by the prevailing party’s transfer of the res from the district.","cite":"506 U.S. 80, 88-89"},{"src":"brief","b":3,"text":"simply restat[ing] the rule that the court must have actual or constructive control of the res when an in rem forfeiture suit is initiated.","cite":"506 U.S. at 87"},{"src":"argument","who":"Mr. Hallward-Driemeier","text":"-- and the -- the -- the -- so the -- I would point the Court to both this Court's decision Republic Bank of Miami, which is not a bankruptcy case, granted, but where the Court seemed to understand that because the United States was a party before it and had, indeed, brought the action, then a court order to undo the -- the transfer would be honored by the United States."},{"src":"argument","who":"Ms. Sinzdak","text":"Among other things, this Court's decision in Republic National Bank rejected the existence of the very limit on in rem jurisdiction that Respondent now asserts."},{"src":"argument","who":"Mr. Hallward-Driemeier","text":"With respect to the general proposition that the ship has sailed, this Court explicitly rejected that proposition in Republic National Bank."}]},{"t":"case","label":"Rockwell Int’l Corp. v. United States","cite":"549 U.S. 457","y":2007,"id":"2006/05-1272","sc":1,"by":{"1":"15, 16"},"q":[{"src":"brief","b":1,"text":"the jurisdictional nature of the original-source requirement is clear ex visceribus verborum.","cite":"549 U.S. at 468"},{"src":"opinion","who":"Opinion of the Court (Justice Jackson)","text":"`[n]o court shall have jurisdiction over [a covered] action,'","cite":"549 U. S. 457, 467–468"}]},{"t":"case","label":"Ross v. Blake","cite":"578 U.S. 632","y":2016,"id":"2015/15-339","sc":1,"by":{"1":"27"}},{"t":"case","label":"Tenet v. Doe","cite":"544 U.S. 1","y":2005,"id":"2004/03-1395","sc":1,"by":{"1":"19"}},{"t":"case","label":"Town of Chester v. Laroe Estates, Inc.","cite":"137 S. Ct. 1645","y":2017,"id":"2016/16-605","sc":1,"by":{"1":"18"}},{"t":"case","label":"United States v. Navajo Nation","cite":"556 U.S. 287","y":2009,"id":"2008/07-1410","sc":1,"by":{"1":"14, 18"}},{"t":"case","label":"United States v. Palomar-Santiago","cite":"141 S. Ct. 1615","y":2021,"id":"2020/20-437","sc":1,"by":{"1":"27"}},{"t":"case","label":"Weingarten Nostat, Inc. v. Service Merch. Co.","cite":"396 F.3d 737","y":2005,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.3d/396/737/","by":{"1":"21","2":"33, 34, 36"},"q":[{"src":"brief","b":1,"text":"particular need to encourage participation in bankruptcy asset sales and increase the value of the property of the estate by protecting good faith purchasers from modification by an appeals court of the bargain struck with the debtor.","cite":"396 F.3d 737, 741"}]},{"t":"const","label":"Article III","clauses":[["judicial-vesting","Judicial Vesting Clause"],["cases-controversies","Cases or Controversies (Justiciability)"],["original-jurisdiction","Original and Appellate Jurisdiction"],["treason","Treason Clause"]],"by":{"1":"8, 9, 11, 12"}},{"t":"usc","label":"11 U.S.C. § 301","url":"https://www.law.cornell.edu/uscode/text/11/301","by":{"1":"17"}},{"t":"usc","label":"11 U.S.C. § 305","url":"https://www.law.cornell.edu/uscode/text/11/305","subs":["(c)"],"by":{"1":"17"},"q":[{"src":"brief","b":1,"text":"is not reviewable by appeal or otherwise by the court of appeals under section 158(d), 1291, or 1292 of title 28 or by the Supreme Court of the United States under section 1254 of title 28.","cite":"11 U.S.C. 305(c)"}]},{"t":"usc","label":"11 U.S.C. § 307","url":"https://www.law.cornell.edu/uscode/text/11/307","by":{"1":"1"}},{"t":"usc","label":"11 U.S.C. § 362","url":"https://www.law.cornell.edu/uscode/text/11/362","subs":["(b)"],"by":{"1":"19"}},{"t":"usc","label":"11 U.S.C. § 262","url":"https://www.law.cornell.edu/uscode/text/11/262","subs":["(c)"],"by":{"1":"19"}},{"t":"usc","label":"8 U.S.C. § 1252","url":"https://www.law.cornell.edu/uscode/text/8/1252","by":{"1":"8, 13, 18, 19"}},{"t":"usc","label":"28 U.S.C. § 581-589a","url":"https://www.law.cornell.edu/uscode/text/28/581-589a","by":{"1":"1"}},{"t":"usc","label":"28 U.S.C. § 1291","url":"https://www.law.cornell.edu/uscode/text/28/1291","by":{"1":"3"}},{"t":"usc","label":"28 U.S.C. § 1292","url":"https://www.law.cornell.edu/uscode/text/28/1292","by":{"1":"3"}},{"t":"usc","label":"28 U.S.C. § 1332","url":"https://www.law.cornell.edu/uscode/text/28/1332","by":{"1":"8, 13"}},{"t":"usc","label":"28 U.S.C. § 2075","url":"https://www.law.cornell.edu/uscode/text/28/2075","subs":["(1970)"],"by":{"1":"24","2":"46"}},{"t":"usc","label":"28 U.S.C. § 2107","url":"https://www.law.cornell.edu/uscode/text/28/2107","subs":["(c)"],"by":{"1":"22","3":"16"}},{"t":"usc","label":"31 U.S.C. § 3729","url":"https://www.law.cornell.edu/uscode/text/31/3729","by":{"1":"15"}},{"t":"usc","label":"31 U.S.C. § 3730","url":"https://www.law.cornell.edu/uscode/text/31/3730","subs":["(e)(4)(A)(2006)"],"by":{"1":"16"}},{"t":"case","label":"Acme Harvester Co. v. Beekman Lumber Co.","cite":"222 U.S. 300","y":1911,"id":"scdb/1911-024","sc":1,"by":{"2":"5"}},{"t":"case","label":"Already, LLC v. Nike, Inc.","cite":"568 U.S. 85","y":2013,"id":"2012/11-982","sc":1,"by":{"2":"22, 23"}},{"t":"case","label":"Bender v. Williamsport Area Sch. Dist.","cite":"475 U.S. 534","y":1986,"id":"1985/84-773","sc":1,"by":{"2":"23"}},{"t":"case","label":"Cal. Pub. Emps Ret. Sys. v. ANZ Sec., Inc.","cite":"137 S. Ct. 2042","y":2017,"id":"2016/16-373","sc":1,"by":{"2":"29"},"q":[{"src":"brief","b":2,"text":"is close to a dispositive indication that the statute is one of repose.","cite":"137 S. Ct. 2042, 2049"}]},{"t":"case","label":"Carlsbad Tech., Inc. v. HIF Bio, Inc.","cite":"556 U.S. 635","id":"2008/07-1437","sc":1,"by":{"2":"37, 38"},"q":[{"src":"brief","b":2,"text":"‘[s]ubject matter jurisdiction defines the court’s authority to hear a given type of case,’","cite":"556 U.S. 635, 639"}]},{"t":"case","label":"City of Milwaukee v. Illinois","cite":"451 U.S. 304","y":1981,"id":"1980/79-408","sc":1,"by":{"2":"30"}},{"t":"case","label":"Cohen v. de la Cruz","cite":"523 U.S. 213","y":1998,"id":"1997/96-1923","sc":1,"by":{"2":"44"}},{"t":"case","label":"Commodity Futures Trading Comm’n v. Weintraub","cite":"471 U.S. 343","y":1985,"id":"1984/84-261","sc":1,"by":{"2":"6"}},{"t":"case","label":"Country Fairways, Inc. v. Mottaz","cite":"539 F.2d 637","y":1976,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.2d/539/637/","by":{"2":"44, 45, 46"}},{"t":"case","label":"Eurasia Int’l, Ltd. v. Holman Shipping, Inc.","cite":"411 F.3d 578","y":2005,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.3d/411/578/","by":{"2":"41"}},{"t":"case","label":"Fed. Election Comm’n v. Nat’l Conservative Political Action Comm.","cite":"470 U.S. 480","y":1985,"id":"1984/83-1032","sc":1,"by":{"2":"32"}},{"t":"case","label":"Fink v. Cont’l Foundry & Mach. Co.","cite":"240 F.2d 369","y":1957,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.2d/240/369/","by":{"2":"45","3":"18"},"q":[{"src":"argument","who":"Mr. Brunstad","text":"The two seminal cases were Fink and Taylor. Taylor involved a situation where there were assets in bankruptcy that were sold, and then the Committee of Creditors appealed and the court of appeals said we don't have jurisdiction to decide this controversy."},{"src":"argument","who":"Mr. Hallward-Driemeier","text":"It is the rule applied by Fink and other cases cited. Now, mind you, Gray, Voorhees, et cetera, were never cited in the briefs, and I don't know what they say."}]},{"t":"case","label":"Genesis Healthcare Corp. v. Symczyk","cite":"569 U.S. 66","y":2013,"id":"2012/11-1059","sc":1,"by":{"2":"23"}},{"t":"case","label":"Gross v. Irving Tr. Co.","cite":"289 U.S. 342","y":1933,"id":"scdb/1932-054","sc":1,"by":{"2":"5"}},{"t":"case","label":"Hanover Nat’l Bank v. Moyses","cite":"186 U.S. 181","y":1902,"id":"scdb/1901-152","sc":1,"by":{"2":"5"}},{"t":"case","label":"Hartford Underwriters Ins. Co. v. Union Planters Bank, N.A.","cite":"530 U.S. 1","y":2000,"id":"1999/99-409","sc":1,"by":{"2":"32"}},{"t":"case","label":"Hollingsworth v. Perry","cite":"570 U.S. 693","y":2013,"id":"2012/12-144","sc":1,"by":{"2":"32"},"q":[{"src":"brief","b":2,"text":"a litigant must assert his or her own legal rights and interests,","cite":"570 U.S. 693, 708"}]},{"t":"case","label":"Isaacs v. Hobbs Tie & Timber Co.","cite":"282 U.S. 734","y":1931,"id":"scdb/1930-165","sc":1,"by":{"2":"6"}},{"t":"case","label":"Kaukauna Water-Power Co. v. Green Bay & Miss. Canal Co.","cite":"142 U.S. 254","y":1891,"id":"scdb/1891-062","sc":1,"by":{"2":"30"}},{"t":"case","label":"Kowalski v. Tesmer","cite":"543 U.S. 125","y":2004,"id":"2004/03-407","sc":1,"by":{"2":"32, 33"}},{"t":"case","label":"Krebs Chrysler-Plymouth, Inc. v. Valley Motors, Inc.","cite":"141 F.3d 490","y":1998,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.3d/141/490/","by":{"2":"7, 35, 36","3":"23"}},{"t":"case","label":"Lewis v. Cont’l Bank Corp.","cite":"494 U.S. 472","y":1990,"id":"1989/87-1955","sc":1,"by":{"2":"22, 23"}},{"t":"case","label":"Midlantic Nat’l Bank v. N.J. Dep’t of Envtl. Prot.","cite":"474 U.S. 494","y":1986,"id":"1985/84-801","sc":1,"by":{"2":"25, 44"}},{"t":"case","label":"Mills v. Green","cite":"159 U.S. 651","y":1895,"id":"scdb/1895-037","sc":1,"by":{"2":"23"},"q":[{"src":"brief","b":2,"text":"to declare principles or rules of law which cannot affect the matter at issue in the case before it.","cite":"159 U.S. 651, 653"}]},{"t":"case","label":"Mission Prods. Holdings, Inc. v. Tempnology, LLC","cite":"139 S. Ct. 1652","y":2019,"id":"2018/17-1657","sc":1,"by":{"2":"passim"}},{"t":"case","label":"Murphy v. Hunt","cite":"455 U.S. 478","y":1982,"id":"1981/80-2165","sc":1,"by":{"2":"23"}},{"t":"case","label":"Newpark Shipbuilding & Repair, Inc. v. M/V Trinton Brute","cite":"2 F.3d 572","y":1993,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.3d/2/572/","by":{"2":"41"}},{"t":"case","label":"Powers v. Ohio","cite":"499 U.S. 400","y":1991,"id":"1990/89-5011","sc":1,"by":{"2":"32"}},{"t":"case","label":"Quincy Mo. & Pac. R.R. Co. v. Humphreys","cite":"145 U.S. 82","y":1892,"id":"scdb/1891-215","sc":1,"by":{"2":"34"}},{"t":"case","label":"Robertson v. Howard","cite":"229 U.S. 254","y":1913,"id":"scdb/1912-233","sc":1,"by":{"2":"6"}},{"t":"case","label":"Shriver v. Woodbine Sav. Bank","cite":"285 U.S. 467","y":1932,"id":"scdb/1931-052","sc":1,"by":{"2":"30"}},{"t":"case","label":"Sobel v. Whittier Corp.","cite":"195 F.2d 361","y":1952,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.2d/195/361/","by":{"2":"45"}},{"t":"case","label":"Spokeo, Inc. v. Robins","cite":"578 U.S. 330","y":2016,"id":"2015/13-1339","sc":1,"by":{"2":"32"},"q":[{"src":"brief","b":2,"text":"(1) suffered an injury in fact, (2) that is fairly traceable to the challenged conduct of the defendant, and (3) that is likely to be redressed by a favorable judicial decision.","cite":"578 U.S. 330, 338"}]},{"t":"case","label":"Sterling v. Blackwelder","cite":"405 F.2d 884","y":1969,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.2d/405/884/","by":{"2":"45, 46"}},{"t":"case","label":"Straton v. New","cite":"283 U.S. 318","y":1931,"id":"scdb/1930-154","sc":1,"by":{"2":"5, 39"}},{"t":"case","label":"Taggart v. Lorenzen","cite":"139 S. Ct. 1795","y":2019,"id":"2018/18-489","sc":1,"by":{"2":"25, 44"}},{"t":"case","label":"Taylor v. Austrian","cite":"154 F.2d 107","y":1946,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.2d/154/107/","by":{"2":"45, 46"}},{"t":"case","label":"Tenn. Student Assistance Corp. v. Hood","cite":"541 U.S. 440","y":2004,"id":"2003/02-1606","sc":1,"by":{"2":"2, 5, 39, 42"}},{"t":"case","label":"TransUnion LLC v. Ramirez","cite":"141 S. Ct. 2190","y":2021,"id":"2020/20-297","sc":1,"by":{"2":"32"}},{"t":"case","label":"U.S. Fid. & Guar. Co. v. Bray","cite":"225 U.S. 205","y":1912,"id":"scdb/1911-065","sc":1,"by":{"2":"5"}},{"t":"case","label":"United States v. One Parcel of Real Estate at 3262 SW 141 Ave.","cite":"33 F.3d 1299","y":1994,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.3d/33/1299/","by":{"2":"41"}},{"t":"case","label":"United States v. Mack","cite":"295 U.S. 480","y":1935,"id":"scdb/1934-132","sc":1,"by":{"2":"24, 39"}},{"t":"case","label":"United States v. Morton","cite":"467 U.S. 822","y":1984,"id":"1983/83-916","sc":1,"by":{"2":"37, 38"}},{"t":"case","label":"United States v. The Little Charles","cite":"26 F. Cas. 979","y":1818,"court":"C.C.D. Va.","url":"https://www.courtlistener.com/c/F.%20Cas./26/979/","by":{"2":"39"},"q":[{"src":"argument","who":"Mr. Hallward-Driemeier","text":"But, to the extent that they purport to establish a rule similar to their characterization of The Ann or The Little Charles, again, this Court specifically rejected that in Republic National Bank."}]},{"t":"case","label":"United Student Aid Funds, Inc. v. Espinosa","cite":"559 U.S. 260","y":2010,"id":"2009/08-1134","sc":1,"by":{"2":"30"},"q":[{"src":"brief","b":2,"text":"only in the rare instance where a judgment is premised either on a certain type of jurisdictional error or on a violation of due process that deprives a party of notice or the opportunity to be heard.","cite":"559 U.S. 260, 270, 271"}]},{"t":"case","label":"Wayne United Gas Co. v. Owens-Ill. Glass Co.","cite":"300 U.S. 131","y":1937,"id":"scdb/1936-087","sc":1,"by":{"2":"31"}},{"t":"const","label":"Article III, Section 2","clauses":[["cases-controversies","Cases or Controversies (Justiciability)"],["original-jurisdiction","Original and Appellate Jurisdiction"]],"text":"The judicial Power shall extend to all Cases, in Law and Equity, arising under this Constitution, the Laws of the United States, and Treaties made, or which shall be made, under their Authority;—to all Cases affecting Ambassadors, other public Ministers and Consuls;—to all Cases of admiralty and maritime Jurisdiction;—to Controversies to which the United States shall be a Party;—to Controversies between two or more States;— between a State and Citizens of another State,—between Citizens of different States,—between Citizens of the same State claiming Lands under Grants of different States, and between a State, or the Citizens thereof, and foreign States, Citizens or Subjects. In all Cases affecting Ambassadors, other public Ministers and Consuls, and those in which a State shall be Party, the supreme Court shall have original Jurisdiction. In all the other Cases before mentioned, the supreme Court shall have appellate Jurisdiction, both as to Law and Fact, with such Exceptions, and under such Regulations as the Congress shall make. The Trial of all Crimes, except in Cases of Impeachment, shall be by Jury; and such Trial shall be held in the State where the said Crimes shall have been committed; but when not committed within any State, the Trial shall be at such Place or Places as the Congress may by Law have directed.","by":{"2":"22"}},{"t":"usc","label":"11 U.S.C. § 105","url":"https://www.law.cornell.edu/uscode/text/11/105","subs":["(a)"],"by":{"2":"12, 13"}},{"t":"usc","label":"11 U.S.C. § 157","url":"https://www.law.cornell.edu/uscode/text/11/157","subs":["(a)"],"by":{"2":"5"}},{"t":"usc","label":"11 U.S.C. § 541","url":"https://www.law.cornell.edu/uscode/text/11/541","subs":["(a)"],"by":{"2":"26, 5, 28"}},{"t":"usc","label":"11 U.S.C. § 549","url":"https://www.law.cornell.edu/uscode/text/11/549","subs":["(a)","(d)","(a)(2)"],"stext":{"head":"§549. Postpetition transactions","paras":[[0,"(a) Except as provided in subsection (b) or (c) of this section, the trustee may avoid a transfer of property of the estate—"],[1,"(1) that occurs after the commencement of the case; and"],[1,"(2)(A) that is authorized only under section 303(f) or 542(c) of this title; or"],[1,"(B) that is not authorized under this title or by the court."],[0,"(b) In an involuntary case, the trustee may not avoid under subsection (a) of this section a transfer made after the commencement of such case but before the order for relief to the extent any value, including services, but not including satisfaction or securing of a debt that arose before the commencement of the case, is given after the commencement of the case in exchange for such transfer, notwithstanding any notice or knowledge of the case that the transferee has."],[0,"(c) The trustee may not avoid under subsection (a) of this section a transfer of an interest in real property to a good faith purchaser without knowledge of the commencement of the case and for present fair equivalent value unless a copy or notice of the petition was filed, where a transfer of an interest in such real property may be recorded to perfect such transfer, before such transfer is so perfected that a bona fide purchaser of such real property, against whom applicable law permits such transfer to be perfected, could not acquire an interest that is superior to such interest of such good faith purchaser. A good faith purchaser without knowledge of the commencement of the case and for less than present fair equivalent value has a lien on the property transferred to the extent of any present value given, unless a copy or notice of the petition was so filed before such transfer was so perfected."],[0,"(d) An action or proceeding under this section may not be commenced after the earlier of—"],[1,"(1) two years after the date of the transfer sought to be avoided; or"],[1,"(2) the time the case is closed or dismissed."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/11/549?type=usc&year=mostrecent&link-type=html"},"by":{"2":"passim, 2, 28, 29","3":"2, 9, 10, 11, 9, 11"},"q":[{"src":"brief","b":3,"text":"not authorized * * * by the court.","cite":"11 U.S.C. 549(a)"},{"src":"brief","b":3,"text":"not authorized * * * by the court,","cite":"11 U.S.C. 549(a)(2)"},{"src":"argument","who":"Mr. Hallward-Driemeier","text":"They say the only remedy is Section 549. But Section 549 here is a two-year period of repose. It's also the debtor's cause of action subject to waiver."},{"src":"argument","who":"Ms. Sinzdak","text":"Nor should Respondent prevail based on its new argument that Section 549 and 550 provide the exclusive means to unwind the disputed lease assignment."},{"src":"argument","who":"Mr. Brunstad","text":"They apply not only to good faith purchasers -- that's Section 549 and Section 550 -- but also bad faith purchasers. There is a specific provision of Section 363 that allows for overturning a sale to bad faith purchasers, 363(n)."}]},{"t":"usc","label":"11 U.S.C. § 550","url":"https://www.law.cornell.edu/uscode/text/11/550","subs":["(a)","(d)","(e)"],"by":{"2":"2, 20, 27, 28, 28, 29, 32, 28, 29, 30, 31"},"q":[{"src":"argument","who":"Mr. Brunstad","text":"They apply not only to good faith purchasers -- that's Section 549 and Section 550 -- but also bad faith purchasers. There is a specific provision of Section 363 that allows for overturning a sale to bad faith purchasers, 363(n)."},{"src":"argument","who":"Mr. Brunstad","text":"Under the statutory mechanisms, all of those reliance interests of the purchaser are preserved if the -- if the transfer is avoided under Section 550."}]},{"t":"usc","label":"11 U.S.C. § 704","url":"https://www.law.cornell.edu/uscode/text/11/704","by":{"2":"6"}},{"t":"usc","label":"11 U.S.C. § 1110","url":"https://www.law.cornell.edu/uscode/text/11/1110","by":{"2":"7"}},{"t":"usc","label":"11 U.S.C. § 1101","url":"https://www.law.cornell.edu/uscode/text/11/1101","by":{"2":"6"}},{"t":"usc","label":"11 U.S.C. § 1106","url":"https://www.law.cornell.edu/uscode/text/11/1106","by":{"2":"6"}},{"t":"usc","label":"11 U.S.C. § 1107","url":"https://www.law.cornell.edu/uscode/text/11/1107","by":{"2":"6"}},{"t":"usc","label":"11 U.S.C. § 1108","url":"https://www.law.cornell.edu/uscode/text/11/1108","by":{"2":"6"}},{"t":"usc","label":"28 U.S.C. § 2465","url":"https://www.law.cornell.edu/uscode/text/28/2465","by":{"2":"40"},"q":[{"src":"brief","b":2,"text":"property shall be returned forthwith to the claimant.","cite":"28 U.S.C. § 2465"}]},{"t":"usc","label":"42 U.S.C. § 11046","url":"https://www.law.cornell.edu/uscode/text/42/11046","subs":["(a)"],"by":{"2":"47"}},{"t":"usc","label":"42 U.S.C. § 2000e","url":"https://www.law.cornell.edu/uscode/text/42/2000e","subs":["(b)"],"by":{"2":"48"}},{"t":"rule","label":"Fed. R. Civ. P. 60","url":"https://www.law.cornell.edu/rules/frcp/rule_60","subs":["(b)"],"by":{"2":"30"}},{"t":"case","label":"Bastian v. Lakefront Realty Corp.","cite":"581 F.2d 685","y":1978,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.2d/581/685/","by":{"3":"18"},"q":[{"src":"brief","b":3,"text":"the action can be undone by orders directed to parties before the court,","cite":"581 F.2d 685, 691"}]},{"t":"case","label":"Bennett v. Robison (In re Combined Metals Reduction Co.)","cite":"557 F.2d 179","y":1977,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.2d/557/179/","by":{"3":"18"},"q":[{"src":"brief","b":3,"text":"not a party to th[e] litigation.","cite":"557 F.2d 179, 193"}]},{"t":"case","label":"Gardner v. United States (In re Gardner)","cite":"913 F.2d 1515","y":1990,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.2d/913/1515/","by":{"3":"8"}},{"t":"case","label":"Gonzalez v. Thaler","cite":"565 U.S. 134","y":2012,"id":"2011/10-895","sc":1,"by":{"3":"13"}},{"t":"case","label":"L.R.S.C. Co. v. Rickel Home Ctrs., Inc. (In re Rickel Home Ctrs., Inc.)","cite":"209 F.3d 291","y":2000,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.3d/209/291/","by":{"3":"23"}},{"t":"case","label":"M.R.R. Traders, Inc. v. Cave Atlantique, Inc.","cite":"788 F.2d 816","y":1986,"court":"1st Cir.","url":"https://www.courtlistener.com/c/F.2d/788/816/","by":{"3":"7"}},{"t":"case","label":"Marshall v. Marshall","cite":"547 U.S. 293","y":2006,"id":"2005/04-1544","sc":1,"by":{"3":"5"}},{"t":"case","label":"Stern v. Marshall","cite":"564 U.S. 462","y":2011,"id":"2010/10-179","sc":1,"by":{"3":"5"}},{"t":"case","label":"Taylor v. Lake (In re CADA Invs., Inc.)","cite":"664 F.2d 1158","y":1981,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.2d/664/1158/","by":{"3":"18"}},{"t":"case","label":"Union Pac. R.R. v. Brotherhood of Locomotive Eng’rs","cite":"558 U.S. 67","y":2009,"id":"2009/08-604","sc":1,"by":{"3":"13"}},{"t":"case","label":"Wolverton v. Shell Oil Co.","cite":"442 F.2d 666","y":1971,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.2d/442/666/","by":{"3":"7"}},{"t":"case","label":"Wood v. Wood (In re Wood)","cite":"825 F.2d 90","y":1987,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.2d/825/90/","by":{"3":"5"}},{"t":"usc","label":"17 U.S.C. § 411","url":"https://www.law.cornell.edu/uscode/text/17/411","subs":["(a)"],"by":{"3":"16"}}]};